import{_ as e,o as i,c as s,a2 as t}from"./chunks/framework.C0KMm31j.js";const n="/Nav2ArticlesSite/article-assets/2026-07-14/behavior_server_cover.png",o="/Nav2ArticlesSite/article-assets/2026-07-14/behavior_server_01_lifecycle.png",l="/Nav2ArticlesSite/article-assets/2026-07-14/behavior_server_02_action_chain.png",p="/Nav2ArticlesSite/article-assets/2026-07-14/behavior_server_03_timed_loop.png",r="/Nav2ArticlesSite/article-assets/2026-07-14/behavior_server_04_collision.png",d="/Nav2ArticlesSite/article-assets/2026-07-14/behavior_server_05_plugins.png",c="/Nav2ArticlesSite/article-assets/2026-07-14/behavior_server_06_output.png",E=JSON.parse('{"title":"机器人“自救”时，数据到底怎么流？拆解 Nav2 Behavior Server 全链路","description":"规划失败后原地旋转、控制失败后短距离后退、等待障碍物离开、在遥控速度可能撞障碍物时主动限速——这些动作看起来很简单，但它们不是几段散落的速度控制代码。","frontmatter":{"title":"机器人“自救”时，数据到底怎么流？拆解 Nav2 Behavior Server 全链路","description":"规划失败后原地旋转、控制失败后短距离后退、等待障碍物离开、在遥控速度可能撞障碍物时主动限速——这些动作看起来很简单，但它们不是几段散落的速度控制代码。","date":"2026-07-14","section":"一 · 架构与启动","readingTime":12,"source":"2026-07-14/behavior_server_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-14/behavior_server_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/behavior-server-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"机器人“自救”时，数据到底怎么流？拆解 Nav2 Behavior Server 全链路"}],["meta",{"property":"og:description","content":"规划失败后原地旋转、控制失败后短距离后退、等待障碍物离开、在遥控速度可能撞障碍物时主动限速——这些动作看起来很简单，但它们不是几段散落的速度控制代码。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/behavior-server-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-14/behavior_server_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-14"}],["meta",{"name":"twitter:title","content":"机器人“自救”时，数据到底怎么流？拆解 Nav2 Behavior Server 全链路"}],["meta",{"name":"twitter:description","content":"规划失败后原地旋转、控制失败后短距离后退、等待障碍物离开、在遥控速度可能撞障碍物时主动限速——这些动作看起来很简单，但它们不是几段散落的速度控制代码。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-14/behavior_server_cover.png"}]],"prev":false,"next":{"text":"没有 AMCL，Nav2 怎么跑？拆解 `map→base_link` 自研定位的实车全数据流","link":"/nav2/myagv-entry-full-dataflow"}},"headers":[],"relativePath":"nav2/behavior-server-full-dataflow.md","filePath":"nav2/behavior-server-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/behavior-server-full-dataflow.md"};function k(v,a,u,g,_,b){return i(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="机器人-自救-时-数据到底怎么流-拆解-nav2-behavior-server-全链路" tabindex="-1">机器人“自救”时，数据到底怎么流？拆解 Nav2 Behavior Server 全链路 <a class="header-anchor" href="#机器人-自救-时-数据到底怎么流-拆解-nav2-behavior-server-全链路" aria-label="Permalink to &quot;机器人“自救”时，数据到底怎么流？拆解 Nav2 Behavior Server 全链路&quot;">​</a></h1><p><img src="'+n+`" alt="behavior_server 封面"></p><p>规划失败后原地旋转、控制失败后短距离后退、等待障碍物离开、在遥控速度可能撞障碍物时主动限速——这些动作看起来很简单，但它们不是几段散落的速度控制代码。</p><p>在 Nav2 中，它们被组织成一套完整的行为服务系统：行为树发出 Action Goal，<code>behavior_server</code> 装载对应插件，插件读取 TF、局部代价地图和机器人轮廓，向前预测运动是否安全，再发布速度、反馈执行进度，最后把结果送回行为树。</p><p>本文以本项目源码 <code>navigation2/nav2_behaviors/src/behavior_server.cpp</code> 为入口，沿着真实代码把这条链路拆到底。</p><p>读完你会得到四个答案：</p><ul><li><code>behavior_server.cpp</code> 自己做什么，又刻意不做什么？</li><li>Spin、BackUp、DriveOnHeading、Wait、AssistedTeleop 的输入输出如何流动？</li><li>代价地图、Footprint、TF 和 <code>cmd_vel</code> 如何形成安全闭环？</li><li>取消、失败、新目标和生命周期切换时，系统怎样收尾？</li></ul><hr><h2 id="一、先给结论-behavior-server-是-行为插件容器-不是动作算法本身" tabindex="-1">一、先给结论：Behavior Server 是“行为插件容器”，不是动作算法本身 <a class="header-anchor" href="#一、先给结论-behavior-server-是-行为插件容器-不是动作算法本身" aria-label="Permalink to &quot;一、先给结论：Behavior Server 是“行为插件容器”，不是动作算法本身&quot;">​</a></h2><p><code>BehaviorServer</code> 的职责可以压缩为五件事：</p><ul><li>声明并读取行为相关参数。</li><li>建立 TF、代价地图和 Footprint 数据入口。</li><li>通过 pluginlib 动态创建行为插件。</li><li>把共享的碰撞检查器交给每个插件。</li><li>统一管理插件的 configure、activate、deactivate 和 cleanup。</li></ul><p>真正的旋转、后退、直行、等待和辅助遥控算法，分别位于 <code>Spin</code>、<code>BackUp</code>、<code>DriveOnHeading</code>、<code>Wait</code>、<code>AssistedTeleop</code> 插件中。</p><p>它们又共同继承 <code>TimedBehavior&lt;ActionT&gt;</code>。这个模板类负责 Action Server、执行循环、取消处理、反馈与结果，以及 <code>cmd_vel</code> 发布器。</p><p>因此，整体结构不是“一个 Server 写死五套动作”，而是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BehaviorServer</span></span>
<span class="line"><span>  ├── 管理生命周期与共享数据</span></span>
<span class="line"><span>  ├── pluginlib 装载 nav2_core::Behavior</span></span>
<span class="line"><span>  └── 每个插件继承 TimedBehavior&lt;ActionT&gt;</span></span>
<span class="line"><span>        ├── 通用 Action 执行框架</span></span>
<span class="line"><span>        └── 插件自己的 onRun() / onCycleUpdate()</span></span></code></pre></div><p>源码构造函数的默认插件列表只有 <code>spin</code>、<code>backup</code>、<code>drive_on_heading</code> 和 <code>wait</code>。但本项目的 <code>myworld2.yaml</code> 与 <code>nav2_params.yaml</code> 都显式配置了 <code>assisted_teleop</code>，因此当前工程实际装载 5 个插件。</p><hr><h2 id="二、生命周期-先把数据通道接好-再允许行为接单" tabindex="-1">二、生命周期：先把数据通道接好，再允许行为接单 <a class="header-anchor" href="#二、生命周期-先把数据通道接好-再允许行为接单" aria-label="Permalink to &quot;二、生命周期：先把数据通道接好，再允许行为接单&quot;">​</a></h2><p><img src="`+o+`" alt="BehaviorServer 生命周期与插件装载"></p><h3 id="_2-1-构造阶段-只声明-不执行" tabindex="-1">2.1 构造阶段：只声明，不执行 <a class="header-anchor" href="#_2-1-构造阶段-只声明-不执行" aria-label="Permalink to &quot;2.1 构造阶段：只声明，不执行&quot;">​</a></h3><p><code>BehaviorServer</code> 是名为 <code>behavior_server</code> 的 Lifecycle Node。构造时主要声明以下参数：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">costmap_topic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">local_costmap/costmap_raw</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">footprint_topic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">local_costmap/published_footprint</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cycle_frequency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">behavior_plugins</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">spin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">backup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">drive_on_heading</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">wait</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">global_frame</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">odom</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">robot_base_frame</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">base_link</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">transform_tolerance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span></span></code></pre></div><p>如果 <code>behavior_plugins</code> 仍是默认列表，构造函数还会声明 <code>spin.plugin</code>、<code>backup.plugin</code> 等插件类型参数。</p><p>注意：参数的最终值以启动时加载的 YAML 为准。本项目的两套配置都把 <code>assisted_teleop</code> 加入列表；实车配置使用 <code>global_frame: map</code>、<code>robot_base_frame: base_link</code>，仿真配置使用 <code>global_frame: odom</code>、<code>robot_base_frame: base_footprint</code>。</p><h3 id="_2-2-configure-阶段-建立共享基础设施" tabindex="-1">2.2 Configure 阶段：建立共享基础设施 <a class="header-anchor" href="#_2-2-configure-阶段-建立共享基础设施" aria-label="Permalink to &quot;2.2 Configure 阶段：建立共享基础设施&quot;">​</a></h3><p><code>on_configure()</code> 依次完成：</p><h4 id="_2-2-1-创建-tf-buffer-与-transform-listener" tabindex="-1">2.2.1 创建 TF Buffer 与 Transform Listener <a class="header-anchor" href="#_2-2-1-创建-tf-buffer-与-transform-listener" aria-label="Permalink to &quot;2.2.1 创建 TF Buffer 与 Transform Listener&quot;">​</a></h4><p>创建 <code>tf2_ros::Buffer</code> 和 <code>TransformListener</code>。</p><h4 id="_2-2-2-订阅-local-costmap" tabindex="-1">2.2.2 订阅 Local Costmap <a class="header-anchor" href="#_2-2-2-订阅-local-costmap" aria-label="Permalink to &quot;2.2.2 订阅 Local Costmap&quot;">​</a></h4><p>订阅 <code>local_costmap/costmap_raw</code>。</p><h4 id="_2-2-3-订阅机器人-footprint" tabindex="-1">2.2.3 订阅机器人 Footprint <a class="header-anchor" href="#_2-2-3-订阅机器人-footprint" aria-label="Permalink to &quot;2.2.3 订阅机器人 Footprint&quot;">​</a></h4><p>订阅 <code>local_costmap/published_footprint</code>。</p><h4 id="_2-2-4-创建碰撞检查器" tabindex="-1">2.2.4 创建碰撞检查器 <a class="header-anchor" href="#_2-2-4-创建碰撞检查器" aria-label="Permalink to &quot;2.2.4 创建碰撞检查器&quot;">​</a></h4><p>创建共享的 <code>CostmapTopicCollisionChecker</code>。</p><h4 id="_2-2-5-读取行为插件类型" tabindex="-1">2.2.5 读取行为插件类型 <a class="header-anchor" href="#_2-2-5-读取行为插件类型" aria-label="Permalink to &quot;2.2.5 读取行为插件类型&quot;">​</a></h4><p>遍历 <code>behavior_plugins</code>，读取每个 <code>&lt;id&gt;.plugin</code>。</p><h4 id="_2-2-6-创建行为插件实例" tabindex="-1">2.2.6 创建行为插件实例 <a class="header-anchor" href="#_2-2-6-创建行为插件实例" aria-label="Permalink to &quot;2.2.6 创建行为插件实例&quot;">​</a></h4><p>通过 <code>plugin_loader_.createUniqueInstance()</code> 创建插件。</p><h4 id="_2-2-7-配置行为插件" tabindex="-1">2.2.7 配置行为插件 <a class="header-anchor" href="#_2-2-7-配置行为插件" aria-label="Permalink to &quot;2.2.7 配置行为插件&quot;">​</a></h4><p>调用插件的 <code>configure()</code>，传入节点、插件名、TF 和碰撞检查器。</p><p>插件基类是 <code>nav2_core::Behavior</code>。只要某个插件类型拼写错误、共享库找不到，或者插件配置抛出异常，整个 <code>BehaviorServer</code> 的 configure 都会失败，不会带着一半插件进入工作状态。</p><h3 id="_2-3-activate-阶段-action-server-才真正接单" tabindex="-1">2.3 Activate 阶段：Action Server 才真正接单 <a class="header-anchor" href="#_2-3-activate-阶段-action-server-才真正接单" aria-label="Permalink to &quot;2.3 Activate 阶段：Action Server 才真正接单&quot;">​</a></h3><p><code>on_activate()</code> 会激活每个插件，并创建 Lifecycle Bond。插件内部随之激活：</p><ul><li><code>cmd_vel</code> Lifecycle Publisher；</li><li>对应的 SimpleActionServer；</li><li>插件自己的订阅或其他资源。</li></ul><p>只有节点处于 ACTIVE 状态，目标才会进入行为执行循环。</p><h3 id="_2-4-deactivate-与-cleanup-停止接单-再释放资源" tabindex="-1">2.4 Deactivate 与 Cleanup：停止接单，再释放资源 <a class="header-anchor" href="#_2-4-deactivate-与-cleanup-停止接单-再释放资源" aria-label="Permalink to &quot;2.4 Deactivate 与 Cleanup：停止接单，再释放资源&quot;">​</a></h3><p>deactivate 会禁用插件的 Action Server 和速度发布器，并销毁 Bond。cleanup 则进一步清空插件实例，释放 TF、代价地图订阅器、Footprint 订阅器和碰撞检查器。</p><p>这套顺序很重要：先停止外部请求，再拆内部资源，避免行为执行到一半时依赖对象已经消失。</p><hr><h2 id="三、请求从哪里来-行为树把恢复动作转换成-action-goal" tabindex="-1">三、请求从哪里来：行为树把恢复动作转换成 Action Goal <a class="header-anchor" href="#三、请求从哪里来-行为树把恢复动作转换成-action-goal" aria-label="Permalink to &quot;三、请求从哪里来：行为树把恢复动作转换成 Action Goal&quot;">​</a></h2><p><img src="`+l+`" alt="从行为树到行为插件的 Action 数据链"></p><p>默认的 <code>navigate_to_pose_w_replanning_and_recovery.xml</code> 中，系统级恢复分支是：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">RoundRobin</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RecoveryActions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Sequence</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ClearingActions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;...&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Sequence</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Spin</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> spin_dist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.57&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Wait</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wait_duration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;5&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">BackUp</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> backup_dist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.30&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> backup_speed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.05&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">RoundRobin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>当规划或控制在局部恢复后仍然失败，行为树按 RoundRobin 顺序尝试清图、旋转、等待和后退。</p><p>以 Spin 为例，数据链是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;Spin spin_dist=&quot;1.57&quot;/&gt;</span></span>
<span class="line"><span>  → SpinAction 读取 BT 端口</span></span>
<span class="line"><span>  → 构造 nav2_msgs/action/Spin Goal</span></span>
<span class="line"><span>  → 发送到 /spin</span></span>
<span class="line"><span>  → Spin 插件的 SimpleActionServer 接收</span></span>
<span class="line"><span>  → TimedBehavior::execute()</span></span>
<span class="line"><span>  → Spin::onRun() / onCycleUpdate()</span></span></code></pre></div><p>5 个行为对应 5 个 Action Server：</p><table tabindex="0"><thead><tr><th>行为插件</th><th>Action 名称</th><th>Goal 关键字段</th><th>Feedback</th></tr></thead><tbody><tr><td>Spin</td><td><code>/spin</code></td><td><code>target_yaw</code>、<code>time_allowance</code></td><td><code>angular_distance_traveled</code></td></tr><tr><td>BackUp</td><td><code>/backup</code></td><td><code>target</code>、<code>speed</code>、<code>time_allowance</code></td><td><code>distance_traveled</code></td></tr><tr><td>DriveOnHeading</td><td><code>/drive_on_heading</code></td><td><code>target</code>、<code>speed</code>、<code>time_allowance</code></td><td><code>distance_traveled</code></td></tr><tr><td>Wait</td><td><code>/wait</code></td><td><code>time</code></td><td><code>time_left</code></td></tr><tr><td>AssistedTeleop</td><td><code>/assisted_teleop</code></td><td><code>time_allowance</code></td><td><code>current_teleop_duration</code></td></tr></tbody></table><p>所有结果都包含 <code>total_elapsed_time</code>。</p><p>Spin、Wait 和 BackUp 直接出现在默认恢复树中。DriveOnHeading 可用于直线运动或里程计标定行为树；AssistedTeleop 是独立的辅助遥控行为，并不在默认导航恢复 RoundRobin 中。</p><hr><h2 id="四、timedbehavior-五个插件共用的一台执行状态机" tabindex="-1">四、TimedBehavior：五个插件共用的一台执行状态机 <a class="header-anchor" href="#四、timedbehavior-五个插件共用的一台执行状态机" aria-label="Permalink to &quot;四、TimedBehavior：五个插件共用的一台执行状态机&quot;">​</a></h2><p><img src="`+p+'" alt="TimedBehavior 统一执行状态机"></p><p>每个插件在 configure 时，<code>TimedBehavior&lt;ActionT&gt;</code> 都会创建：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SimpleActionServer&lt;ActionT&gt;(behavior_name)</span></span>\n<span class="line"><span>LifecyclePublisher&lt;Twist&gt;(&quot;cmd_vel&quot;)</span></span></code></pre></div><p>当 Action Goal 到达，<code>execute()</code> 按以下顺序工作。</p><h3 id="_4-1-确认节点仍然启用" tabindex="-1">4.1 确认节点仍然启用 <a class="header-anchor" href="#_4-1-确认节点仍然启用" aria-label="Permalink to &quot;4.1 确认节点仍然启用&quot;">​</a></h3><p>若插件没有 ACTIVE，目标不会进入动作算法。</p><h3 id="_4-2-调用一次-onrun-goal" tabindex="-1">4.2 调用一次 <code>onRun(goal)</code> <a class="header-anchor" href="#_4-2-调用一次-onrun-goal" aria-label="Permalink to &quot;4.2 调用一次 `onRun(goal)`&quot;">​</a></h3><p>这是插件的“起跑准备”阶段，负责：</p><ul><li>校验 Goal 参数；</li><li>查询初始 TF；</li><li>保存起始位姿或起始角度；</li><li>计算 time allowance；</li><li>初始化插件状态。</li></ul><p><code>onRun()</code> 返回失败，执行直接终止，不进入周期循环。</p><h3 id="_4-3-以-cycle-frequency-循环" tabindex="-1">4.3 以 <code>cycle_frequency</code> 循环 <a class="header-anchor" href="#_4-3-以-cycle-frequency-循环" aria-label="Permalink to &quot;4.3 以 `cycle_frequency` 循环&quot;">​</a></h3><p>本项目配置为 <code>10 Hz</code>。每一轮先检查取消和 pending goal，再调用 <code>onCycleUpdate()</code>。</p><p>插件返回三种内部状态：</p><ul><li><code>RUNNING</code>：睡眠到下一周期；</li><li><code>SUCCEEDED</code>：填入耗时并成功结束当前 Goal；</li><li><code>FAILED</code>：填入耗时并终止当前 Goal。</li></ul><h3 id="_4-4-处理取消与新-goal" tabindex="-1">4.4 处理取消与新 Goal <a class="header-anchor" href="#_4-4-处理取消与新-goal" aria-label="Permalink to &quot;4.4 处理取消与新 Goal&quot;">​</a></h3><p>收到取消时，框架会调用 <code>stopRobot()</code> 发布零 Twist，然后终止全部目标。</p><p>收到新 Goal 时，当前 Humble 版本明确记录“preemption not implemented”，同样先停车并终止当前 Goal。也就是说，这套行为 Action 不是无缝抢占模型。</p><p>这里还要区分 AssistedTeleop 的 <code>preempt_teleop</code> 话题：它是辅助遥控插件自己的“正常结束遥控”信号，不等于 Action Server 收到一个 pending goal。</p><hr><h2 id="五、碰撞检查-不是看当前位置-而是先看未来会不会撞" tabindex="-1">五、碰撞检查：不是看当前位置，而是先看未来会不会撞 <a class="header-anchor" href="#五、碰撞检查-不是看当前位置-而是先看未来会不会撞" aria-label="Permalink to &quot;五、碰撞检查：不是看当前位置，而是先看未来会不会撞&quot;">​</a></h2><p><img src="'+r+'" alt="预测位姿与碰撞检查闭环"></p><h3 id="_5-1-获取碰撞检查输入" tabindex="-1">5.1 获取碰撞检查输入 <a class="header-anchor" href="#_5-1-获取碰撞检查输入" aria-label="Permalink to &quot;5.1 获取碰撞检查输入&quot;">​</a></h3><p>共享的 <code>CostmapTopicCollisionChecker</code> 接收两类数据：</p><ul><li><code>local_costmap/costmap_raw</code>：局部代价地图快照。</li><li><code>local_costmap/published_footprint</code>：机器人实时轮廓。</li></ul><p>插件再通过 TF 获取机器人当前位姿，把候选速度向未来积分，得到一串预测 <code>Pose2D</code>。</p><h3 id="_5-2-检查每个预测位姿" tabindex="-1">5.2 检查每个预测位姿 <a class="header-anchor" href="#_5-2-检查每个预测位姿" aria-label="Permalink to &quot;5.2 检查每个预测位姿&quot;">​</a></h3><p>对每个预测位姿，碰撞检查器执行以下步骤。</p><h4 id="_5-2-1-变换机器人-footprint" tabindex="-1">5.2.1 变换机器人 Footprint <a class="header-anchor" href="#_5-2-1-变换机器人-footprint" aria-label="Permalink to &quot;5.2.1 变换机器人 Footprint&quot;">​</a></h4><p>把机器人 Footprint 旋转、平移到预测位姿。</p><h4 id="_5-2-2-映射代价地图网格" tabindex="-1">5.2.2 映射代价地图网格 <a class="header-anchor" href="#_5-2-2-映射代价地图网格" aria-label="Permalink to &quot;5.2.2 映射代价地图网格&quot;">​</a></h4><p>将世界坐标映射到代价地图网格。</p><h4 id="_5-2-3-计算覆盖区域代价" tabindex="-1">5.2.3 计算覆盖区域代价 <a class="header-anchor" href="#_5-2-3-计算覆盖区域代价" aria-label="Permalink to &quot;5.2.3 计算覆盖区域代价&quot;">​</a></h4><p>计算 Footprint 覆盖区域的代价值。</p><h4 id="_5-2-4-判断致命障碍" tabindex="-1">5.2.4 判断致命障碍 <a class="header-anchor" href="#_5-2-4-判断致命障碍" aria-label="Permalink to &quot;5.2.4 判断致命障碍&quot;">​</a></h4><p>判断是否达到 <code>LETHAL_OBSTACLE</code>。</p><p>如果预测位姿落到地图之外、代价地图不可用、Footprint 不可用，检查器也按“不安全”处理。</p><p>为了减少同一轮预测中的重复复制，插件通常只在第一个预测点刷新 Costmap 和 Footprint，后续预测点复用同一份快照。这样同一条预测轨迹基于一致的数据时刻，同时降低循环开销。</p><h3 id="_5-3-spin-的预测" tabindex="-1">5.3 Spin 的预测 <a class="header-anchor" href="#_5-3-spin-的预测" aria-label="Permalink to &quot;5.3 Spin 的预测&quot;">​</a></h3><p>Spin 以当前角速度在 <code>simulate_ahead_time</code> 内逐步增加 yaw，检查原地旋转时的轮廓是否扫到障碍物。</p><h3 id="_5-4-driveonheading-与-backup-的预测" tabindex="-1">5.4 DriveOnHeading 与 BackUp 的预测 <a class="header-anchor" href="#_5-4-driveonheading-与-backup-的预测" aria-label="Permalink to &quot;5.4 DriveOnHeading 与 BackUp 的预测&quot;">​</a></h3><p>两者以候选线速度沿当前朝向积分 x、y，检查未来直线路径上的每个机器人轮廓。</p><h3 id="_5-5-assistedteleop-的预测" tabindex="-1">5.5 AssistedTeleop 的预测 <a class="header-anchor" href="#_5-5-assistedteleop-的预测" aria-label="Permalink to &quot;5.5 AssistedTeleop 的预测&quot;">​</a></h3><p>它同时积分线速度和角速度。若第一步就碰撞，直接把速度置零；若更远处才碰撞，则按“安全时间 ÷ projection_time”缩放整条 Twist，使机器人越接近风险速度越小。</p><hr><h2 id="六、五个插件的数据流差异" tabindex="-1">六、五个插件的数据流差异 <a class="header-anchor" href="#六、五个插件的数据流差异" aria-label="Permalink to &quot;六、五个插件的数据流差异&quot;">​</a></h2><p><img src="'+d+`" alt="五类行为插件数据流"></p><h3 id="_6-1-spin-目标角度-→-已转角-→-制动角速度" tabindex="-1">6.1 Spin：目标角度 → 已转角 → 制动角速度 <a class="header-anchor" href="#_6-1-spin-目标角度-→-已转角-→-制动角速度" aria-label="Permalink to &quot;6.1 Spin：目标角度 → 已转角 → 制动角速度&quot;">​</a></h3><p><code>Spin::onRun()</code> 先用 TF 获取起始姿态，记录目标 yaw 和允许时间。</p><p>每周期再次获取当前姿态，通过相邻 yaw 差并处理 <code>±π</code> 跳变，累计真实旋转角度。剩余角度用于计算制动速度：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rot_vel = sqrt(2 × rotational_acc_lim × remaining_yaw)</span></span></code></pre></div><p>随后把速度限制在 <code>min_rotational_vel</code> 与 <code>max_rotational_vel</code> 之间，再根据目标方向设置正负号。碰撞预测通过后，发布只有 <code>angular.z</code> 的 Twist。</p><p>达到目标、超时或预测碰撞时，Spin 会先发布零速，再返回成功或失败。</p><h3 id="_6-2-driveonheading-目标距离-→-实际位移-→-受限线速度" tabindex="-1">6.2 DriveOnHeading：目标距离 → 实际位移 → 受限线速度 <a class="header-anchor" href="#_6-2-driveonheading-目标距离-→-实际位移-→-受限线速度" aria-label="Permalink to &quot;6.2 DriveOnHeading：目标距离 → 实际位移 → 受限线速度&quot;">​</a></h3><p>Goal 只允许使用 <code>target.x</code>，<code>target.y</code> 和 <code>target.z</code> 必须为零，而且 target 与 speed 的符号必须一致。</p><p>插件用当前位姿与起始位姿之间的欧氏距离作为 <code>distance_traveled</code>。候选速度由目标速度、每周期加速度、减速度和剩余制动距离共同决定。</p><p>如果 acceleration/deceleration 参数均为零，就直接使用 Goal speed；否则按周期限制速度变化，并在接近目标时减速。</p><h3 id="_6-3-backup-先把方向强制为负-再复用直行算法" tabindex="-1">6.3 BackUp：先把方向强制为负，再复用直行算法 <a class="header-anchor" href="#_6-3-backup-先把方向强制为负-再复用直行算法" aria-label="Permalink to &quot;6.3 BackUp：先把方向强制为负，再复用直行算法&quot;">​</a></h3><p>BackUp 继承 DriveOnHeading。它不重新实现周期控制，只在 <code>onRun()</code> 中把：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>target.x = -abs(target.x)</span></span>
<span class="line"><span>speed    = -abs(speed)</span></span></code></pre></div><p>然后复用 DriveOnHeading 的距离反馈、速度约束、前向预测和结果处理。</p><p>这里的“前向预测”指沿候选速度积分；当速度为负时，预测轨迹自然向机器人后方展开。</p><h3 id="_6-4-wait-只消费时钟-不产生运动" tabindex="-1">6.4 Wait：只消费时钟，不产生运动 <a class="header-anchor" href="#_6-4-wait-只消费时钟-不产生运动" aria-label="Permalink to &quot;6.4 Wait：只消费时钟，不产生运动&quot;">​</a></h3><p>Wait 保存 <code>now + goal.time</code> 为结束时刻。每周期计算 <code>time_left</code> 并发布反馈，到零后成功返回。</p><p>它不读取 TF，不读取代价地图，也不发布运动 Twist。</p><h3 id="_6-5-assistedteleop-把人工速度变成碰撞约束后的速度" tabindex="-1">6.5 AssistedTeleop：把人工速度变成碰撞约束后的速度 <a class="header-anchor" href="#_6-5-assistedteleop-把人工速度变成碰撞约束后的速度" aria-label="Permalink to &quot;6.5 AssistedTeleop：把人工速度变成碰撞约束后的速度&quot;">​</a></h3><p>AssistedTeleop 订阅 <code>cmd_vel_teleop</code>，保存最新人工速度；每周期从 TF 获取当前位姿，并在 <code>projection_time</code> 内按 <code>simulation_time_step</code> 向前投影。</p><p>输出可能是：</p><ul><li>原始遥控速度；</li><li>按碰撞时间比例缩小后的速度；</li><li>零速度。</li></ul><p>达到 time allowance 会失败并停车；收到 <code>preempt_teleop</code> 信号会停车并成功结束。</p><hr><h2 id="七、输出链路-behavior-server-的速度不经过-velocity-smoother" tabindex="-1">七、输出链路：Behavior Server 的速度不经过 Velocity Smoother <a class="header-anchor" href="#七、输出链路-behavior-server-的速度不经过-velocity-smoother" aria-label="Permalink to &quot;七、输出链路：Behavior Server 的速度不经过 Velocity Smoother&quot;">​</a></h2><p><img src="`+c+`" alt="速度输出、反馈、取消与故障边界"></p><p>当前 <code>navigation_launch.py</code> 对 Controller Server 做了如下重映射：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>controller_server: cmd_vel → cmd_vel_nav</span></span>
<span class="line"><span>velocity_smoother:  cmd_vel_nav → cmd_vel</span></span></code></pre></div><p>但 Behavior Server 只应用 TF remapping，没有把 <code>cmd_vel</code> 重映射为 <code>cmd_vel_nav</code>。</p><p>因此两条速度路径不同：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正常路径跟踪：controller_server → cmd_vel_nav → velocity_smoother → cmd_vel</span></span>
<span class="line"><span>恢复／行为动作：behavior_server ─────────────────────────────→ cmd_vel</span></span></code></pre></div><p>这意味着 Spin、BackUp、DriveOnHeading 和 AssistedTeleop 的速度直接进入最终 <code>cmd_vel</code>，不会再经过当前 Nav2 Velocity Smoother。</p><p>调参和排障时不能只观察 <code>cmd_vel_nav</code>。如果导航恢复阶段机器人在动而 <code>cmd_vel_nav</code> 没有数据，这是预期现象，应同时检查 <code>/spin</code>、<code>/backup</code> 等 Action 状态和最终 <code>/cmd_vel</code>。</p><p>它也意味着行为插件自己的速度限制、加减速和停车分支更加关键。</p><hr><h2 id="八、结果如何回到行为树" tabindex="-1">八、结果如何回到行为树 <a class="header-anchor" href="#八、结果如何回到行为树" aria-label="Permalink to &quot;八、结果如何回到行为树&quot;">​</a></h2><p>插件每周期通过 Action Feedback 返回进度。Behavior Tree 的 Action 节点接收后维持 RUNNING，直到收到最终结果。</p><p>常见闭环如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spin 成功</span></span>
<span class="line"><span>  → /spin Action succeeded</span></span>
<span class="line"><span>  → BT Spin 节点返回 SUCCESS</span></span>
<span class="line"><span>  → RoundRobin 当前恢复动作完成</span></span>
<span class="line"><span>  → 外层 RecoveryNode 再次执行规划与控制</span></span></code></pre></div><p>如果行为失败，BT 节点返回 FAILURE，恢复控制节点根据重试次数和 RoundRobin 状态决定尝试下一个动作，或让整次导航失败。</p><p>取消导航时，取消会从上层 Action 传播到当前 BT Action 节点，再取消具体行为 Action。TimedBehavior 收到取消后发布零速并结束目标。</p><hr><h2 id="九、源码审查中值得特别注意的三个边界" tabindex="-1">九、源码审查中值得特别注意的三个边界 <a class="header-anchor" href="#九、源码审查中值得特别注意的三个边界" aria-label="Permalink to &quot;九、源码审查中值得特别注意的三个边界&quot;">​</a></h2><h3 id="_9-1-框架的-failed-分支不统一补发零速" tabindex="-1">9.1 框架的 FAILED 分支不统一补发零速 <a class="header-anchor" href="#_9-1-框架的-failed-分支不统一补发零速" aria-label="Permalink to &quot;9.1 框架的 FAILED 分支不统一补发零速&quot;">​</a></h3><p><code>TimedBehavior::execute()</code> 在取消和不支持的抢占分支会显式调用 <code>stopRobot()</code>，但插件返回 <code>FAILED</code> 时，通用框架只终止当前 Goal，没有统一再发布一次零速。</p><p>Spin 和 DriveOnHeading 在超时、碰撞等主要失败路径会自行停车；但在周期中获取当前 TF 失败的分支，代码直接返回 <code>FAILED</code>，没有先调用 <code>stopRobot()</code>。</p><p>因此新增自定义 Behavior 时，不能假设“返回 FAILED 后框架一定停车”。所有可能在此前发布过非零速度的失败路径，都应自行检查是否需要 <code>stopRobot()</code>。</p><h3 id="_9-2-costmap-和-behavior-的-global-frame-必须一致可转换" tabindex="-1">9.2 Costmap 和 Behavior 的 global_frame 必须一致可转换 <a class="header-anchor" href="#_9-2-costmap-和-behavior-的-global-frame-必须一致可转换" aria-label="Permalink to &quot;9.2 Costmap 和 Behavior 的 global_frame 必须一致可转换&quot;">​</a></h3><p>行为插件用 <code>global_frame → robot_base_frame</code> 获取当前姿态，碰撞检查使用订阅到的局部代价地图。</p><p>仿真配置中两者都是 <code>odom</code>；实车配置中两者都是 <code>map</code>。若修改其中一处却没有同步另一处，可能出现位姿查询成功但碰撞坐标不一致，或 TF 直接失败。</p><h3 id="_9-3-behavior-action-不支持无缝-goal-抢占" tabindex="-1">9.3 Behavior Action 不支持无缝 Goal 抢占 <a class="header-anchor" href="#_9-3-behavior-action-不支持无缝-goal-抢占" aria-label="Permalink to &quot;9.3 Behavior Action 不支持无缝 Goal 抢占&quot;">​</a></h3><p>收到 pending goal 时，当前实现会停车并终止当前目标，而不是接受新目标继续执行。上层若需要连续改变旋转角度或直行距离，应先明确取消、等待终态，再发送新 Goal。</p><hr><h2 id="十、排障时按这条顺序查" tabindex="-1">十、排障时按这条顺序查 <a class="header-anchor" href="#十、排障时按这条顺序查" aria-label="Permalink to &quot;十、排障时按这条顺序查&quot;">​</a></h2><h3 id="_10-1-行为插件没有出现" tabindex="-1">10.1 行为插件没有出现 <a class="header-anchor" href="#_10-1-行为插件没有出现" aria-label="Permalink to &quot;10.1 行为插件没有出现&quot;">​</a></h3><p>检查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lifecycle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /behavior_server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /behavior_server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> behavior_plugins</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> action</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;spin|backup|drive_on_heading|wait|assisted_teleop&#39;</span></span></code></pre></div><p>如果节点无法 configure，重点检查 <code>&lt;id&gt;.plugin</code> 类型名和 pluginlib 导出 XML。</p><h3 id="_10-2-action-一直-running-但机器人不动" tabindex="-1">10.2 Action 一直 RUNNING，但机器人不动 <a class="header-anchor" href="#_10-2-action-一直-running-但机器人不动" aria-label="Permalink to &quot;10.2 Action 一直 RUNNING，但机器人不动&quot;">​</a></h3><p>检查最终输出而不是只看平滑器输入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /cmd_vel</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /local_costmap/costmap_raw</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /local_costmap/published_footprint</span></span></code></pre></div><p>同时确认 <code>global_frame</code> 到 <code>robot_base_frame</code> 的 TF 可用。</p><h3 id="_10-3-行为一启动就报碰撞" tabindex="-1">10.3 行为一启动就报碰撞 <a class="header-anchor" href="#_10-3-行为一启动就报碰撞" aria-label="Permalink to &quot;10.3 行为一启动就报碰撞&quot;">​</a></h3><p>依次核对：</p><h4 id="_10-3-1-核对-footprint" tabindex="-1">10.3.1 核对 Footprint <a class="header-anchor" href="#_10-3-1-核对-footprint" aria-label="Permalink to &quot;10.3.1 核对 Footprint&quot;">​</a></h4><p>确认 Footprint 是否与真实车体一致。</p><h4 id="_10-3-2-核对机器人自身障碍" tabindex="-1">10.3.2 核对机器人自身障碍 <a class="header-anchor" href="#_10-3-2-核对机器人自身障碍" aria-label="Permalink to &quot;10.3.2 核对机器人自身障碍&quot;">​</a></h4><p>确认局部代价地图是否把机器人自身标成障碍物。</p><h4 id="_10-3-3-核对-costmap-范围" tabindex="-1">10.3.3 核对 Costmap 范围 <a class="header-anchor" href="#_10-3-3-核对-costmap-范围" aria-label="Permalink to &quot;10.3.3 核对 Costmap 范围&quot;">​</a></h4><p>确认当前位姿是否落在 Costmap 范围内。</p><h4 id="_10-3-4-核对预测时间" tabindex="-1">10.3.4 核对预测时间 <a class="header-anchor" href="#_10-3-4-核对预测时间" aria-label="Permalink to &quot;10.3.4 核对预测时间&quot;">​</a></h4><p>确认 <code>simulate_ahead_time</code> 是否过大。</p><h4 id="_10-3-5-核对频率匹配" tabindex="-1">10.3.5 核对频率匹配 <a class="header-anchor" href="#_10-3-5-核对频率匹配" aria-label="Permalink to &quot;10.3.5 核对频率匹配&quot;">​</a></h4><p>确认速度、周期频率和地图更新频率是否匹配。</p><h3 id="_10-4-取消后仍观察到速度" tabindex="-1">10.4 取消后仍观察到速度 <a class="header-anchor" href="#_10-4-取消后仍观察到速度" aria-label="Permalink to &quot;10.4 取消后仍观察到速度&quot;">​</a></h3><p>先确认速度来自哪个发布者：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /cmd_vel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span></span></code></pre></div><p>Behavior Server 和 Velocity Smoother 都可能发布最终 <code>cmd_vel</code>。必须区分是行为取消未生效，还是另一条控制链仍在输出。</p><hr><h2 id="十一、把完整数据流压缩成一张脑图" tabindex="-1">十一、把完整数据流压缩成一张脑图 <a class="header-anchor" href="#十一、把完整数据流压缩成一张脑图" aria-label="Permalink to &quot;十一、把完整数据流压缩成一张脑图&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>导航失败或独立行为请求</span></span>
<span class="line"><span>  → BT Action 节点构造 Goal</span></span>
<span class="line"><span>  → /spin /backup /drive_on_heading /wait /assisted_teleop</span></span>
<span class="line"><span>  → TimedBehavior::execute()</span></span>
<span class="line"><span>      → onRun() 校验与初始化</span></span>
<span class="line"><span>      → 10 Hz onCycleUpdate()</span></span>
<span class="line"><span>          → TF 获取当前位姿</span></span>
<span class="line"><span>          → 计算进度与候选速度</span></span>
<span class="line"><span>          → Costmap + Footprint 前向碰撞预测</span></span>
<span class="line"><span>          → 发布 Feedback</span></span>
<span class="line"><span>          → 发布 cmd_vel 或零速</span></span>
<span class="line"><span>      → Action Result</span></span>
<span class="line"><span>  → BT 收到 SUCCESS / FAILURE</span></span>
<span class="line"><span>  → 重试导航、切换恢复动作或结束任务</span></span></code></pre></div><p><code>behavior_server.cpp</code> 的价值，不是亲自计算每一个动作，而是把插件、生命周期、共享环境数据和 Action 执行框架稳定地拼在一起。</p><p>理解这条数据链之后，再定位“为什么不旋转”“为什么一后退就失败”“为什么恢复速度没经过平滑器”，就不需要在整个 Nav2 中盲找：先看 Action，再看 TF 与碰撞输入，然后看插件周期状态，最后看最终 <code>cmd_vel</code>。</p><p>这就是 Behavior Server 真正的系统边界。</p>`,192)])])}const F=e(h,[["render",k]]);export{E as __pageData,F as default};
